<body>
<canvas id="c" width="400" height="600"></canvas>
<div class="ov" id="ov"><h1>CRYPT OF THE SHADOW KING</h1><p class="title-sub">PRESS SPACE TO ENTER</p></div>
<div class="ct"><button class="kpr" data-a="pause">P</button><button class="kpr" data-a="attack">Space</button></div>

<script>
// ---- Audio (Web Audio API) ----
const ac = new AudioContext();
function sfx(t, type){
  const o=ac.createOscillator();o.type=type;o.frequency.value=t;
  o.connect(ac.destination);o.start(0);
  setTimeout(()=>{o.stop()},100);
}
function beep(freq,dur=0.08){sfx(dur,freq);}

// ---- Game state ----
let floor=1, HP=5, GOLD=0, keysDown=false, mute=false, gameOver=false;
const T=32; // tile size
let pX=200,pY=300;ang=0;
let explored={}; // floor -> array of {x,y,w,h}
let enemies=[]; items=[]; keysPicked=[]; minimapX=10,minimapY=10;

// ---- Helpers ----
function rand(a,b){return Math.floor(Math.random()*Math.max(1,a-b)+a);}
function dist(x1,y1,x2,y2)=Math.hypot(x1-x2,y1-y2);
function inRoom(x,y,rx,ry){return x>=rx && x<rx+T && y>=ry && y<ry+T;}
function spawnDungeon(){
  let floors=[];
  for(let f=1;f<=3;f++){
    let rooms=[];let xs=0,ys=0;
    while(xs<400 && ys<600){
      let r=rand(4,5);
      const rw=r*40+8;
      const rh=r*32+16;
      let rx=xs+rw/2,ys+rh/2;
      rooms.push({x:xs,y:ys,w:rw,h:rh});
      xs+=rw+4; ys+=rh+4;
    }
    floors.push(rooms);
  }
  return floors;
}
function spawnEnemies(){
  enemies=[];
  for(let f=1;f<=floor;f++){
    let rnd=rand(0,3);
    if(rnd===0) enemies.push({t:'rat',x:50,y:150});
    else if(rnd===1) enemies.push({t:'skeleton',x:300,y:200});
    else if(rnd===2) enemies.push({t:'mage',x:100,y:250});
  }
}
function spawnItems(){
  items=[];
  for(let f=1;f<=floor;f++){
    let xs=Math.floor(Math.random()*400);
    let ys=Math.floor(Math.random()*600);
    if(ys<300) items.push({t:'potion',x:xs,y:ys});
    else if(ys<450) items.push({t:'key',x:xs,y:ys});
  }
}
function spawnChest(){
  items.push({t:'chest',x:rand(0,400),y:rand(0,600)});
}
function usePotion(){HP+=2;drawHeart(HP/10);} // placeholder
function heal(){HP=Math.min(HP+2,5)}
function takeDamage(dmg){
  HP-=dmg;
  if(HP<=0){gameOver=true; spawnBoss();}
  sfx(Math.random()*200,'thud'); drawFlash();
  ctx.fillStyle='#fff';ctx.font='14px monospace';ctx.textAlign='center';
  ctx.fillText('HIT! '+dmg+' HP', pX,pY);
}

// ---- Drawing helpers ----
function clear(){ctx.clearRect(0,0,H);}
function drawRect(x,y,w,h,c){
  for(let i=0;i<w;i++){for(let j=0;j<h;j++){ctx.fillStyle=c||'#111';ctx.fillRect(x+i*32,y+j*32,32,32);}}
}
function drawWall(){ // gray stone
  ctx.fillStyle='#555';
  for(let x=0;x<400;x+=40){
    for(let y=0;y<600;y+=40){
      ctx.fillRect(x,y,x+40,y+40);
    }
  }
}
function drawDoors(){ // brown wood
  ctx.fillStyle='#8B4513';
  for(let x=0;x<400;x+=40){
    for(let y=0;y<600;y+=40){
      ctx.fillRect(x,y,x+40,y+40);
    }
  }
}
function drawPlayer(x,y){
  // green adventurer
  ctx.fillStyle='#00FF00';
  ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.fill();
  // facing arrow
  ctx.strokeStyle='#00FF00';ctx.lineWidth=1;
  ctx.beginPath();ctx.moveTo(x-3*ang*16,y-3*ang*16);ctx.lineTo(x+3*ang*16,y+3*ang*16);ctx.stroke();
}
function drawSword(x,y,ang){
  ctx.strokeStyle='#FFD700';ctx.lineWidth=2;
  ctx.beginPath();ctx.moveTo(x-4*ang*16,y-4*ang*16);ctx.lineTo(x+4*ang*16,y+4*ang*16);ctx.stroke();
}
function drawEnemies(enemies){
  for(const e of enemies){
    ctx.fillStyle=e.t==='rat'?'#8B4513':'#D3D3D3';
    ctx.fillRect(e.x-6,e.y-6,e.x+12,e.y+12);
  }
}
function drawItems(items){
  for(const it of items){
    if(it.t==='potion'){
      ctx.fillStyle='#00FFFF';ctx.beginPath();ctx.arc(it.x,it.y,4,0,Math.PI*2);ctx.fill();
    }else if(it.t==='key'){
      ctx.fillStyle='#FFD700';
      ctx.beginPath();ctx.rect(it.x-3,it.y-3,6,6);ctx.fill();
    }else if(it.t==='chest'){
      ctx.fillStyle='#8B4513';
      ctx.beginPath();ctx.rect(it.x-4,it.y-4,8,8);ctx.fill();
    }
  }
}
function drawHeart(hp){
  // simple heart above player
  const cx=px?0:0; // placeholder not used
}
function drawFlash(){
  ctx.fillStyle='red';
  ctx.font='30px monospace';ctx.textAlign='center';
  ctx.fillText('HIT!', pX,pY);
}

// ---- Minimap ----
function drawMinimap(){
  ctx.fillStyle='#111';
  for(let i=0;i<minimapX;i++)drawRect(10+i*40,10,i*32+5,20);
  if(floors[floor] && floors[floor].length>0){
    const room=floors[floor][0];
    ctx.fillStyle='#0f0';
    ctx.fillRect(10,10,minimapX*40,20);
  }
}

// ---- Main update (movement) ----
function update(){
  if(gameOver){return;}
  pX+=Math.cos(ang)*5;
  pY+=Math.sin(ang)*5;
}

