document.addEventListener('keydown',e=>{
  if(e.key===' '){keysDown=true;}
  if(e.key==='ArrowUp'){ang=-Math.PI/2;}
  if(e.key==='ArrowDown'){ang=Math.PI/2;}
  if(e.key==='w'||e.key==='W'){ang=-Math.PI/2;}
  if(e.key==='s'||e.key==='S'){ang=Math.PI/2;}
  if(e.key==='p'||e.key==='P'){mute=!mute;}
});
document.addEventListener('keyup',e=>{
  if(e.key===' '){keysDown=false;}
  if(e.key==='ArrowUp'){ang+=Math.PI/2;}
  if(e.key==='ArrowDown'){ang-=Math.PI/2;}
});

// ---- Game loop ----
function gameLoop(){
  update();
  clear();
  // background floor tiles
  for(let r=0;r<floors[floor].length;r++){
    const room=floors[floor][r];
    if(!room){continue;}
    for(let i=0;i<room.w;i++){
      for(let j=0;j<room.h;j++){
        ctx.fillStyle=(i%2===0||j%3===0?'#222':'#333'); // variation
        drawRect(room.x+i*40, room.y+j*32, 40, 32, CSTONE);
      }
    }
  }
