  for(let r=0;r<floors[floor].length;r++){
    const room=floors[floor][r];
    if(!room){continue;}
    ctx.fillStyle='#555';
    drawWall(room.x,room.y,room.w,room.h);
  }
  // doors (brown) at center of each room
  for(let r=0;r<floors[floor].length;r++){
    const room=floors[floor][r];
    if(!room){continue;}
    ctx.fillStyle='#8B4513';
    drawRect(room.x+20,room.y+room.h/2-10, 24, 16);
  }
  // player
  drawPlayer(pX,pY);
  drawSword(pX,pY,ang);
  // enemies
  drawEnemies(enemies);
  // items
  drawItems(items);
  // keys picked
  for(const k of keysPicked){ctx.fillStyle='#FFD700';ctx.beginPath();ctx.arc(k.x,k.y,4,0,Math.PI*2);ctx.fill();}
  // gold
  ctx.fillStyle='#FFD700';
  ctx.font='12px monospace';
  ctx.textAlign='center';
  ctx.fillText(GOLD,'200,50');
  // health bar above player (red/green)
  const barW=16;const barH=4;
  ctx.fillStyle='red';ctx.fillRect(pX-barW/2,pY+barH-1,pX+barW/2,barH);
  ctx.fillStyle='#FFAA00';
  ctx.fillRect(pX-barW/2,pY+barH,pX+barW/2,barH*0.5);
  // floating damage
  if(HP<=3 && HP>0){
    ctx.font='14px monospace';ctx.textAlign='center';
    ctx.fillStyle='#fff';
    ctx.fillText('HIT! '+dmg+' HP', pX,pY+10); // dmg undefined, set below
  }
  drawMinimap();
}

