document.getElementById('ov').innerHTML='';
if(gameOver){
  document.getElementById('ov').innerHTML=`<h1>YOU DIED</h1><p>Floor: ${floor} Gold: ${GOLD}</p><button class="kpr" data-a="restart">R</button><button class="kpr" data-a="pause">P</button>`;
